def test_2225_moves_the_play_fab_id_up_into_the_entry(packet_2225):
    assert bytes(packet_2225) == V2168_ADD[:31] + V2168_ADD[44:49] + V2168_ADD[31:44] + V2168_ADD[49:]


def test_a_2225_body_round_trips(packet_2225):
    assert v2225.PlayerListPacket.from_bytes(bytes(packet_2225)) == packet_2225


def test_a_2225_body_is_not_a_2168_one_of_the_same_length(packet_2225):
    with pytest.raises(ValueError, match="at byte"):
        v2168.PlayerListPacket.from_bytes(bytes(packet_2225))
